from pathlib import Path
import argparse,json,sys,numpy as np
W=Path(__file__).resolve().parent;R=W.parents[1];sys.path.insert(0,str(W.parent/'disect_adaptive_contact_20261109_v27'))
from adaptive_contact import intersections
from tomato_compiled_blade_query import query_mesh
p=argparse.ArgumentParser();p.add_argument('checkpoint');p.add_argument('--output',default='saved_geometry_review.json');a=p.parse_args();z=np.load(a.checkpoint);m=np.load(W.parent/'disect_completion_20261108_v18/conforming_split.npz');q=z['x'];q0=np.load(W.parent/'disect_physical_20261109_v22/settle_contact_final.npz')['x'];pairs=m['ties'];side=np.zeros(len(q),int);side[m['tets'].ravel()]=np.repeat(m['tet_side'],4);neg=np.where(side[pairs[:,0]]<0,pairs[:,0],pairs[:,1]);pos=np.where(side[pairs[:,0]]>0,pairs[:,0],pairs[:,1]);mid=(q[neg]+q[pos])/2;mid0=(q0[neg]+q0[pos])/2
ref=np.load(R/'runs/offline/padded_cad_packet_20261102_01/cad_pressure_reference.npz');A=np.array([[1,0,0],[0,0,-1],[0,1,0]],float);rot=A.T@ref['rotation'];raw=json.loads((R/'runs/offline/tomato_preupgrade_20261027T171031Z/blade_export.json').read_text());T=z['blade_translation'];v=np.array(raw['vertices'])@rot.T+T;faces=np.array(raw['triangles']);query=query_mesh(v,faces,np.concatenate((q[neg],q[pos])));n=len(pairs);phi=np.column_stack((query['phi'][:n],query['phi'][n:]));normals=np.stack((query['normal'][:n],query['normal'][n:]),axis=1)
