out={'scope':'Read-only geometry on actual material vertices and full exact CAD; nearest-face directions are geometric data, not reconstructed forces. This is not a whole-blade path-miss, damage or separation verdict.','checkpoint':str(Path(a.checkpoint).resolve()),'sim_s':float(z['step']*z['dt']),'maximum_history_m':float(z['history'][:,0].max()),'damage_max':float(z['history'][:,1].max()),'front_pair':{'id':front,'positions_m':q[[neg[front],pos[front]]].tolist(),'midpoint_m':point.tolist(),'midpoint_displacement_m':(point-mid0[front]).tolist(),'signed_distances_m':phi[front].tolist(),'nearest_normals':normals[front].tolist(),'full_CAD_inside_intervals_x_at_current_yz_m':intervals},'cut_pairs':{'count':n,'both_vertices_within_0_1mm_CAD_distance':int(near.sum()),'near_pairs_with_opposed_X_faces':int((near&opposed).sum()),'near_pairs_on_same_X_face':int((near&same).sum()),'maximum_raw_twin_distance_m':float(np.linalg.norm(q[neg]-q[pos],axis=1).max())}}
